INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000001, "2030/01/01 14:59:59", 62, 1, -416.5, 2, 1, 1, "2025/01/31 12:00:00", 0.0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000002, "2030/01/01 14:59:59", 62, 1, -416.5, 2, 2, 1, "2025/01/31 12:00:00", 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000003, "2030/01/01 14:59:59", 63, 1, -416.5, 2, 3, 1, "2025/01/31 12:00:00", 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000004, "2030/01/01 14:59:59", 63, 2, -416.5, 2, 4, 1, "2025/01/31 12:00:00", 0.0, "報酬がもらえますよ！\nチェックしてみてください", 0.0, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000005, "2030/01/01 14:59:59", 64, 2, -363.0, 1, 5, 1, "2025/01/31 12:00:00", 0.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000006, "2030/01/01 14:59:59", 64, 1, -363.0, 2, 6, 1, "2025/01/31 12:00:00", 0.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190805, 1000007, "2030/01/01 14:59:59", 64, 2, -363.0, 1, 7, 1, "2025/01/31 12:00:00", 0.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133701, 1020101, "2030/01/01 14:59:59", 61, 3, -285.0, 7, 101, 10201, "2025/01/31 12:00:00", -6.0, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 5.18, "ラビリスタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133901, 1020102, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10201, "2025/01/31 12:00:00", -2.0, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 8.77, "クリスティーナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133801, 1020103, "2030/01/01 14:59:59", 61, 6, -285.0, 1, 301, 10201, "2025/01/31 12:00:00", 0.0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 15.5, "ネネカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134301, 1020201, "2030/01/01 14:59:59", 61, 2, -285.0, 5, 101, 10202, "2025/02/28 12:00:00", 0.0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 9.061, "ランファ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134401, 1020202, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10202, "2025/02/28 12:00:00", 0.0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 7.699, "チカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134601, 1020301, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 101, 10203, "2025/03/31 12:00:00", 0.0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 8.595, "アオイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134501, 1020302, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10203, "2025/03/31 12:00:00", 0.0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 7.758, "クローチェ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (132302, 1020401, "2030/01/01 14:59:59", 61, 2, -285.0, 6, 101, 10204, "2025/04/30 12:00:00", 0.0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 7.0, "ルイズマリー");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (132402, 1020402, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10204, "2025/04/30 12:00:00", 0.0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 7.904, "イロハ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (132502, 1020403, "2030/01/01 14:59:59", 61, 4, -285.0, 2, 301, 10204, "2025/04/30 12:00:00", 0.0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 8.487, "ソノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134901, 1020502, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 101, 10205, "2025/05/31 12:00:00", 0.0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 8.763, "カノン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134801, 1020503, "2030/01/01 14:59:59", 61, 1, -285.0, 3, 201, 10205, "2025/05/31 12:00:00", 0.0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 6.417, "ツムギ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135001, 1020601, "2030/01/01 14:59:59", 61, 3, -285.0, 7, 101, 10206, "2025/06/30 12:00:00", 0.0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10.335, "エリス");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135101, 1020602, "2030/01/01 14:59:59", 61, 2, -285.0, 4, 201, 10206, "2025/06/30 12:00:00", 0.0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 6.281, "シェフィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135201, 1020603, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 301, 10206, "2025/06/30 12:00:00", 0.0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 12.244, "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135301, 1020701, "2030/01/01 14:59:59", 61, 2, -285.0, 8, 101, 10207, "2025/07/31 12:00:00", 0.0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 6.339, "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135401, 1020702, "2030/01/01 14:59:59", 61, 7, -285.0, 9, 201, 10207, "2025/07/31 12:00:00", 0.0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 8.184, "アネモネ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (129101, 1020801, "2030/01/01 14:59:59", 61, 9, -285.0, 2, 101, 10208, "2025/08/31 12:00:00", 0.0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 3.906, "アイラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (129201, 1020802, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10208, "2025/08/31 12:00:00", 0.0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 14.465, "シナツ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (100101, 1020803, "2030/01/01 14:59:59", 61, 4, -285.0, 3, 301, 10208, "2025/08/31 12:00:00", 0.0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 8.662, "ヒヨリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (100301, 1020804, "2030/01/01 14:59:59", 61, 1, -285.0, 3, 401, 10208, "2025/08/31 12:00:00", 0.0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10.915, "レイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135802, 1020901, "2030/01/01 14:59:59", 61, 1, -285.0, 7, 101, 10209, "2025/09/30 12:00:00", 0.0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 6.042, "ユキノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135903, 1020902, "2030/01/01 14:59:59", 61, 4, -285.0, 1, 201, 10209, "2025/09/30 12:00:00", 0.0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 9.402, "サツキ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136902, 1020903, "2030/01/01 14:59:59", 61, 8, -285.0, 1, 301, 10209, "2025/09/30 12:00:00", 0.0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 8.16, "ルルィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (137401, 1021001, "2030/01/01 14:59:59", 61, 3, -285.0, 2, 101, 10210, "2025/10/31 12:00:00", 0.0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 5.0, "カスミ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136001, 1021002, "2030/01/01 14:59:59", 61, 4, -285.0, 1, 201, 10210, "2025/10/31 12:00:00", 0.0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 8.12, "アラクネ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136202, 1021003, "2030/01/01 14:59:59", 61, 4, -285.0, 2, 301, 10210, "2025/10/31 12:00:00", 0.0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 6.386, "ナーナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136402, 1021101, "2030/01/01 14:59:59", 61, 3, -285.0, 4, 101, 10211, "2025/11/30 12:00:00", 0.0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 7.438, "ユイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136302, 1021102, "2030/01/01 14:59:59", 61, 1, -285.0, 5, 201, 10211, "2025/11/30 12:00:00", 0.0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 8.35, "ミソラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136501, 1021201, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 101, 10212, "2025/12/31 12:00:00", 0.0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 5.0, "シズル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (137902, 1021202, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10212, "2025/12/31 12:00:00", 0.0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 5.25, "リノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (106801, 1021203, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 301, 10212, "2025/12/31 12:00:00", 0.0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 7.5, "ラビリスタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126501, 1021301, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 101, 10213, "2026/01/31 12:00:00", 0.0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 8.204, "ライラエル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (129701, 1021302, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10213, "2026/01/31 12:00:00", 0.0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 7.176, "ネフィ＝ネラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133101, 1021303, "2030/01/01 14:59:59", 61, 1, -285.0, 5, 301, 10213, "2026/01/31 12:00:00", 0.0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 8.602, "ヴァイオレット");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138101, 1021304, "2030/01/01 14:59:59", 61, 1, -285.0, 3, 102, 10213, "2026/02/06 12:00:00", 0.0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10.14, "ライラエル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138201, 1021305, "2030/01/01 14:59:59", 61, 1, -285.0, 7, 202, 10213, "2026/02/06 12:00:00", 0.0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10.152, "ネフィ＝ネラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138001, 1021306, "2030/01/01 14:59:59", 61, 4, -285.0, 3, 302, 10213, "2026/02/06 12:00:00", 0.0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 9.688, "ヴァイオレット");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138301, 1021307, "2030/01/01 14:59:59", 61, 2, -285.0, 1, 401, 10213, "2026/02/12 12:00:00", 0.0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 5.928, "ペコリーヌ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138702, 1021401, "2030/01/01 14:59:59", 61, 4, -285.0, 2, 101, 10214, "2026/02/28 12:00:00", 0.0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 9.19, "ワカナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138802, 1021402, "2030/01/01 14:59:59", 61, 1, -285.0, 3, 201, 10214, "2026/02/28 12:00:00", 0.0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 8.724, "シオリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138902, 1021501, "2030/01/01 14:59:59", 61, 4, -285.0, 1, 101, 10215, "2026/03/31 12:00:00", 0.0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 7.758, "グレイス");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139002, 1021502, "2030/01/01 14:59:59", 61, 6, -285.0, 4, 201, 10215, "2026/03/31 12:00:00", 0.0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 6.375, "キョウカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136902, 1021503, "2030/01/01 14:59:59", 61, 6, -285.0, 1, 301, 10215, "2026/03/31 12:00:00", 0.0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 6.173, "ルルィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139202, 1021601, "2030/01/01 14:59:59", 61, 6, -285.0, 2, 101, 10216, "2026/04/30 12:00:00", 0.0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 4.202, "ミホ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139302, 1021602, "2030/01/01 14:59:59", 61, 6, -285.0, 1, 201, 10216, "2026/04/30 12:00:00", 0.0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 2.842, "マホ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139402, 1021603, "2030/01/01 14:59:59", 61, 4, -285.0, 1, 301, 10216, "2026/04/30 12:00:00", 0.0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 4.598, "エリカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (125802, 1021701, "2030/01/01 14:59:59", 61, 4, -285.0, 3, 101, 10217, "2026/05/31 12:00:00", 0.0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 6.533, "リリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126102, 1021702, "2030/01/01 14:59:59", 61, 3, -285.0, 3, 301, 10217, "2026/05/31 12:00:00", 0.0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 5.0, "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126002, 1021703, "2030/01/01 14:59:59", 61, 3, -285.0, 4, 201, 10217, "2026/05/31 12:00:00", 0.0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 5.214, "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139501, 1021704, "2030/01/01 14:59:59", 61, 1, -285.0, 3, 102, 10217, "2026/05/31 12:00:00", 0.0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 8.781, "リリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139601, 1021705, "2030/01/01 14:59:59", 61, 2, -285.0, 1, 202, 10217, "2026/05/31 12:00:00", 0.0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 6.529, "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139701, 1021706, "2030/01/01 14:59:59", 61, 3, -285.0, 2, 302, 10217, "2026/05/31 12:00:00", 0.0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 3.195, "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139902, 1021801, "2030/01/01 14:59:59", 61, 2, -285.0, 3, 101, 10218, "2026/06/30 12:00:00", 0.0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 12.43, "ルイズマリー");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140001, 1021802, "2030/01/01 14:59:59", 61, 2, -285.0, 3, 201, 10218, "2026/06/30 12:00:00", 0.0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 6.35, "クレジッタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140102, 1021901, "2030/01/01 14:59:59", 61, 1, -285.0, 5, 101, 10219, "2026/07/31 12:00:00", 0.0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10.23, "フブキ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140201, 1021902, "2030/01/01 14:59:59", 61, 1, -285.0, 2, 201, 10219, "2026/07/31 12:00:00", 0.0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 5.584, "ヴァンピィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000001, "2030/01/01 14:59:59", 62, 1, -416.5, 2, 1, 2, "2026/04/10 12:00:00", 0.0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000002, "2030/01/01 14:59:59", 62, 1, -416.5, 2, 2, 2, "2026/04/10 12:00:00", 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000003, "2030/01/01 14:59:59", 63, 1, -416.5, 2, 3, 2, "2026/04/10 12:00:00", 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000004, "2030/01/01 14:59:59", 63, 2, -416.5, 2, 4, 2, "2026/04/10 12:00:00", 0.0, "報酬がもらえますよ！\nチェックしてみてください", 0.0, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000005, "2030/01/01 14:59:59", 64, 2, -363.0, 1, 5, 2, "2026/04/10 12:00:00", 0.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000006, "2030/01/01 14:59:59", 64, 1, -363.0, 2, 6, 2, "2026/04/10 12:00:00", 0.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, 2000007, "2030/01/01 14:59:59", 64, 2, -363.0, 1, 7, 2, "2026/04/10 12:00:00", 0.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, "カリン");
